-- Generated from the reviewed browser-visible legacy registration and bank/branch exports.
-- Contains configuration labels/IDs only; no employee values or raw server responses.
-- Organization relationships unavailable in the capture are intentionally not invented.

ALTER TABLE employment_records DROP CONSTRAINT IF EXISTS ck_employment_records_employee_category;
ALTER TABLE employment_records ADD CONSTRAINT ck_employment_records_employee_category
  CHECK (employee_category IN ('MANAGEMENT', 'STAFF', 'WORKER', 'TRAINEE', 'EXECUTIVE'));

CREATE TEMP TABLE legacy_company_seed (id UUID, code VARCHAR(30), name VARCHAR(160)) ON COMMIT DROP;
INSERT INTO legacy_company_seed VALUES
  ('5785cc0d-c990-9bff-6e15-8187529cbdc6', 'LEGACY-1', 'UNION NORTH PVT LTD');

INSERT INTO companies(id, code, name, active, created_by, updated_by)
SELECT id, code, name, TRUE, 'legacy-blueprint-import', 'legacy-blueprint-import'
FROM legacy_company_seed seed
WHERE NOT EXISTS (
  SELECT 1 FROM companies existing
  WHERE regexp_replace(lower(existing.name), '[^a-z0-9]+', '', 'g') =
        regexp_replace(lower(seed.name), '[^a-z0-9]+', '', 'g')
)
ON CONFLICT (code) DO NOTHING;

CREATE TEMP TABLE legacy_company_resolved ON COMMIT DROP AS
SELECT id FROM companies
WHERE code = 'LEGACY-1'
   OR regexp_replace(lower(name), '[^a-z0-9]+', '', 'g') =
      regexp_replace(lower('UNION NORTH PVT LTD'), '[^a-z0-9]+', '', 'g')
ORDER BY (code = 'LEGACY-1') DESC
LIMIT 1;

CREATE TEMP TABLE legacy_location_seed (id UUID, code VARCHAR(30), name VARCHAR(160)) ON COMMIT DROP;
INSERT INTO legacy_location_seed VALUES
  ('e2f3a8fa-f1e3-b10a-8ca5-a8ac4cbb8fe1', 'LEGACY-1', 'Dankotuwa');

INSERT INTO locations(id, company_id, code, name, active, created_by, updated_by)
SELECT seed.id, company.id, seed.code, seed.name, TRUE,
       'legacy-blueprint-import', 'legacy-blueprint-import'
FROM legacy_location_seed seed CROSS JOIN legacy_company_resolved company
WHERE NOT EXISTS (
  SELECT 1 FROM locations existing
  WHERE existing.company_id = company.id AND lower(existing.name) = lower(seed.name)
)
ON CONFLICT (company_id, code) DO NOTHING;

CREATE TEMP TABLE legacy_location_resolved ON COMMIT DROP AS
SELECT location.id
FROM locations location CROSS JOIN legacy_company_resolved company
WHERE location.company_id = company.id
  AND (location.code = 'LEGACY-1'
       OR lower(location.name) = lower('Dankotuwa'))
ORDER BY (location.code = 'LEGACY-1') DESC
LIMIT 1;

