INSERT INTO departments(id, company_id, location_id, code, name, active, created_by, updated_by)
SELECT seed.id, company.id, location.id, seed.code, seed.name, TRUE,
       'legacy-blueprint-import', 'legacy-blueprint-import'
FROM legacy_department_seed seed
CROSS JOIN legacy_company_resolved company
CROSS JOIN legacy_location_resolved location
WHERE NOT EXISTS (
  SELECT 1 FROM departments existing
  WHERE existing.company_id = company.id AND lower(existing.name) = lower(seed.name)
)
ON CONFLICT (company_id, code) DO NOTHING;

