INSERT INTO designations(id, company_id, code, title, active, created_by, updated_by)
SELECT seed.id, company.id, seed.code, seed.name, TRUE,
       'legacy-blueprint-import', 'legacy-blueprint-import'
FROM legacy_designation_seed seed CROSS JOIN legacy_company_resolved company
WHERE NOT EXISTS (
  SELECT 1 FROM designations existing
  WHERE existing.company_id = company.id AND lower(existing.title) = lower(seed.name)
)
ON CONFLICT (company_id, code) DO NOTHING;

