INSERT INTO setup_items(id, kind, code)
SELECT id, kind, code FROM legacy_company_reference_seed
ON CONFLICT (kind, code) DO NOTHING;

INSERT INTO setup_item_revisions(item_id, name, active, effective_from, data, created_by, reason)
SELECT item.id, seed.name, TRUE, DATE '2000-01-01',
       jsonb_build_object('companyId', company.id::text),
       'legacy-blueprint-import', 'Initial browser-observed legacy registration catalog'
FROM legacy_company_reference_seed seed
JOIN setup_items item ON item.kind = seed.kind AND item.code = seed.code
CROSS JOIN legacy_company_resolved company
WHERE NOT EXISTS (SELECT 1 FROM setup_item_revisions revision WHERE revision.item_id = item.id);

CREATE TEMP TABLE legacy_shift_seed (id UUID, code VARCHAR(50), name VARCHAR(160), start_time VARCHAR(5), end_time VARCHAR(5), not_applicable BOOLEAN) ON COMMIT DROP;
