INSERT INTO setup_items(id, kind, code)
SELECT id, 'SHIFT', code FROM legacy_shift_seed
ON CONFLICT (kind, code) DO NOTHING;

INSERT INTO setup_item_revisions(item_id, name, active, effective_from, data, created_by, reason)
SELECT item.id, seed.name, TRUE, DATE '2000-01-01',
       jsonb_build_object(
         'sourceName', seed.name,
         'startTime', seed.start_time,
         'endTime', seed.end_time,
         'breakMinutes', 0,
         'graceMinutes', 0,
         'overnight', FALSE,
         'notApplicable', seed.not_applicable,
         'scheduleVerified', FALSE
       ),
       'legacy-blueprint-import', 'Displayed shift times imported; break and grace rules require review'
FROM legacy_shift_seed seed
JOIN setup_items item ON item.kind = 'SHIFT' AND item.code = seed.code
WHERE NOT EXISTS (SELECT 1 FROM setup_item_revisions revision WHERE revision.item_id = item.id);

