INSERT INTO setup_items(id, kind, code)
SELECT id, 'BANK_BRANCH', item_code FROM legacy_branch_seed
ON CONFLICT (kind, code) DO NOTHING;

INSERT INTO setup_item_revisions(item_id, name, active, effective_from, data, created_by, reason)
SELECT branch_item.id, seed.name, TRUE, DATE '2000-01-01',
       jsonb_build_object('bankId', bank_item.id::text, 'branchCode', seed.branch_code),
       'legacy-blueprint-import', 'Initial browser-observed legacy bank branch catalog'
FROM legacy_branch_seed seed
JOIN setup_items branch_item
  ON branch_item.kind = 'BANK_BRANCH' AND branch_item.code = seed.item_code
JOIN setup_items bank_item
  ON bank_item.kind = 'BANK' AND bank_item.code = seed.bank_code
WHERE NOT EXISTS (
  SELECT 1 FROM setup_item_revisions revision WHERE revision.item_id = branch_item.id
);

CREATE TEMP TABLE legacy_payment_method_seed (id UUID, code VARCHAR(50), name VARCHAR(160), mode VARCHAR(10)) ON COMMIT DROP;
INSERT INTO legacy_payment_method_seed VALUES
  ('e7d43f54-939a-729e-9c81-617a74c98f21', 'BANK', 'Bank', 'BANK'),
  ('72aa67ff-6bd3-dd6c-f6aa-f40f8533c747', 'CASH', 'Cash', 'CASH');

INSERT INTO setup_items(id, kind, code)
SELECT id, 'PAYMENT_METHOD', code FROM legacy_payment_method_seed
ON CONFLICT (kind, code) DO NOTHING;

INSERT INTO setup_item_revisions(item_id, name, active, effective_from, data, created_by, reason)
SELECT item.id, seed.name, TRUE, DATE '2000-01-01',
       jsonb_build_object('mode', seed.mode),
       'legacy-blueprint-import', 'Initial legacy registration payment methods'
FROM legacy_payment_method_seed seed
JOIN setup_items item ON item.kind = 'PAYMENT_METHOD' AND item.code = seed.code
WHERE NOT EXISTS (SELECT 1 FROM setup_item_revisions revision WHERE revision.item_id = item.id);

DO $$
BEGIN
  IF (SELECT count(*) FROM setup_items item JOIN legacy_bank_seed seed
      ON item.kind = 'BANK' AND item.code = seed.code) <> 48 THEN
    RAISE EXCEPTION 'Legacy bank seed count mismatch';
  END IF;
  IF (SELECT count(*) FROM setup_items item JOIN legacy_branch_seed seed
      ON item.kind = 'BANK_BRANCH' AND item.code = seed.item_code) <> 3352 THEN
    RAISE EXCEPTION 'Legacy branch seed count mismatch';
  END IF;
END $$;
